# Code generated by Claude
"""
Test of the retry in the simulator (design plan 8 D4 item 2): the real scripted manipulation module, a failure injected into the first attempt of the pick, the oracle checker (no API call).

    python experiments/mpvi_retry_sim_test.py [--keep DIR]

The first attempt of the pick fails (an injected module error while the hand is above the beaker, 30 ticks into the DOWN waypoint). The orchestrator retries: only the failing (left) arm goes back
to its zombie pose (the real recover(): the fingers open, the hand backs off, the pad centre and the joints go to the zombie pose), the world model is refreshed, the objects are grounded again and the pick runs
again; the plan then finishes. Checks: the episode is SUCCESS and the attempts are logged; every command of the recovery names the left arm only; the right arm's joints did not change
between the failure and the end of the recovery; the left arm is at its zombie pose at the end of the recovery with the fingers open; the pick's objects were grounded twice; the replay of the recording is
bit-identical.
"""

import argparse
import gc
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main(args):
    sim = load_task(cameras=True)
    rec = {"inj": None, "right_after": None, "left_after": None, "finger_after": None, "cmds": []}

    def hook(modules, model, data):
        real = modules["manipulation"]
        right, left = arm_ids(model, "right")["qadr"], arm_ids(model, "left")["qadr"]
        fq = int(model.jnt_qposadr[arm_ids(model, "left")["finger_jnt"][0]])
        S = {"attempt": 0, "ticks": 0, "recovering": False, "err": None}
        m = dict(real)

        def start(seg):
            S.update(attempt=S["attempt"] + 1, ticks=0, recovering=False, err=None)
            real["start"](seg)

        def step(obs):
            cmds = real["step"](obs)
            if S["recovering"]:
                rec["cmds"].append(cmds)
            else:
                S["ticks"] += 1 if real["phase"]() == "DOWN" else 0
                if S["attempt"] == 1 and S["ticks"] > 30 and S["err"] is None:
                    S["err"] = "injected failure (test)"
                    rec["inj"] = {"time": obs["time"], "right": data.qpos[right].copy()}
            return cmds

        def recover():
            S["recovering"], S["err"] = True, None
            real["recover"]()

        def done():
            d = real["done"]()
            if S["recovering"] and d and rec["right_after"] is None:
                rec["right_after"], rec["left_after"], rec["finger_after"] = data.qpos[right].copy(), data.qpos[left].copy(), float(data.qpos[fq])
            return d
        m.update(start=start, step=step, recover=recover, done=done, error=lambda: S["err"] or real["error"]())
        return {**modules, "manipulation": m}

    task = make_pipeline_task(checker="oracle", module_hook=hook)
    out = Path(args.keep) if args.keep else Path(tempfile.mkdtemp(prefix="mpvi_retry_"))
    for sub in ("episode", "recording"):
        shutil.rmtree(out / sub, ignore_errors=True)
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording")
    pipe = task["pipeline"]
    state = pipe["orchestrator"]["state"]
    print(f"\noutcome {s['outcome']}  plan failure: {state['failure']}")
    att = [(a["segment"], a["attempt"], a["outcome"]) for a in state["attempts"]]
    check("the episode outcome is SUCCESS and the plan finished", s["outcome"] == "SUCCESS" and state["finished"] and not state["failure"], f"{s['outcome']} {state['failure']}")
    check("the injected failure was retried: attempt 1 of the pick failed, attempt 2 done", (1, 1, "failed") in att and (1, 2, "done") in att and state["attempts"][[i for i, a in enumerate(att) if a == (1, 1, "failed")][0]]["decision"] == "retry",
          f"{att}")
    check("the pick's objects were grounded twice (once per attempt), the place's once", [g["segment"] for g in state["grounded"]] == [1, 1, 2], f"{state['grounded']}")
    check("every command of the recovery names the left arm only (the other arm is not commanded)", len(rec["cmds"]) > 10 and all(
        set((c or {}).get("arm_targets", {"left": 0})) == {"left"} and set((c or {}).get("gripper", {"left": 0})) == {"left"} for c in rec["cmds"] if isinstance(c, dict)), f"{len(rec['cmds'])} commands")
    dr = float(np.max(np.abs(rec["right_after"] - rec["inj"]["right"]))) if rec["right_after"] is not None else None
    check("the right arm's joints did not change between the failure and the end of the recovery", dr is not None and dr < 2e-3, f"largest change {dr}")
    err = float(np.max(np.abs(rec["left_after"] - np.array(TASK_CFG["home_q_left"])))) if rec["left_after"] is not None else None
    check("at the end of the recovery the left arm is at its zombie pose and the fingers are open", err is not None and err < 0.03 and rec["finger_after"] > TASK_CFG.get("finger_open", 0.044) - 0.003,
          f"largest joint error {err} rad, finger travel {rec['finger_after']}")
    print("\nreplay of the recording")
    del sim, task, pipe
    gc.collect()
    r = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", r["ok"], f"{r['ticks']} ticks, mismatch {r['mismatch']}")
    if not args.keep:
        shutil.rmtree(out, ignore_errors=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--keep", help="keep the episode log and the recording in this directory")
    main(ap.parse_args())
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)
